using Microsoft.AspNetCore.Mvc;\nusing System.Threading.Tasks;\nusing MyProject.Services;\nusing MyProject.Models;\nusing System;\n\nnamespace MyProject.Controllers\n{\n [ApiController]\n [Route("api/[controller]")]\n public class AccountsController : ControllerBase\n {\n private readonly ISalesforceService _service;\n public AccountsController(ISalesforceService service){ _service = service; }\n\n [HttpGet]\n public async Task<IActionResult> GetAccounts([FromQuery] int pageNumber = 1, [FromQuery] int pageSize = 50)\n {\n if (pageNumber < 1) pageNumber = 1;\n if (pageSize < 1) pageSize = 50;\n var result = await _service.GetAccountsAsync(pageNumber, pageSize);\n return Ok(result);\n }\n\n [HttpGet("{id}")]\n public async Task<IActionResult> GetAccount(string id)\n {\n var acc = await _service.GetAccountAsync(id);\n if (acc == null) return NotFound();\n return Ok(acc);\n }\n\n [HttpPost]\n public async Task<IActionResult> CreateAccount([FromBody] AccountDto dto)\n {\n var created = await _service.CreateAccountAsync(dto);\n return CreatedAtAction(nameof(GetAccount), new { id = created.Id }, created);\n }\n\n [HttpPut("{id}")]\n public async Task<IActionResult> UpdateAccount(string id, [FromBody] AccountDto dto)\n {\n var updated = await _service.UpdateAccountAsync(id, dto);\n if (updated == null) return NotFound();\n return Ok(updated);\n }\n\n [HttpDelete("{id}")]\n public async Task<IActionResult> DeleteAccount(string id)\n {\n var deleted = await _service.DeleteAccountAsync(id);\n if (!deleted) return NotFound();\n return NoContent();\n }\n }\n}